/* ---------- chapters: one gesture moves to the next chapter and the passage plays by itself ---------- */
const sinIO=t=>-(Math.cos(Math.PI*t)-1)/2;
const GUIDE={on:false,from:0,to:0,t0:0,dur:0,hold:0,snapT:0,onEnd:null};
let CH=[];
/* a chapter the page cannot scroll to the top of (the last one, if short) starts where the page ends */
function chMeasure(){const dm=docMax();CH=$$('main [data-ch]').map(el=>{const r=el.getBoundingClientRect();return {el,id:el.dataset.ch,top:Math.min(Math.round(r.top+scrollY),dm),h:Math.round(r.height)}})}
