  const lr=(a,b,dy=17)=>{x.font=`400 10px ${M}`;x.textAlign='left';x.fillText(a,P,y);x.textAlign='right';x.fillText(b,RW-P,y);y+=dy};
  const rule=(dy=18)=>{x.save();x.strokeStyle=ink;x.globalAlpha=.55;x.setLineDash([3,3]);x.beginPath();x.moveTo(P,y-4);x.lineTo(RW-P,y-4);x.stroke();x.restore();y+=dy};
  ctr('EMMEZZETA',`600 17px ${M}`,20);
  ctr('MARCO S. ZANINI · MILANO',`400 9px ${M}`,14);
  ctr('DESIGN · DIRECTION · PHOTO',`400 9px ${M}`,22);
  rule();
  const d=new Date(),dd=String(d.getDate()).padStart(2,'0')+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+d.getFullYear();
  lr('RECEIPT 0001',dd);lr('CLIENT','YOU',22);
  rule();
  lr('1 x YOUR IDEA','—');lr('1 x CONCEPT + CREATIVE DIR.','INCL.');lr('1 x IDENTITY + GRAPHICS','INCL.');lr('1 x SET + SHOOT PLANNING','INCL.');lr('1 x PHOTO + POST-PRODUCTION','INCL.');lr('1 x FINAL FILES, ALL FORMATS','INCL.');lr('1 x FUN','100%',22);
  rule();
  x.font=`600 12px ${M}`;x.textAlign='left';x.fillText('TOTAL',P,y);x.textAlign='right';x.fillText('LET’S TALK',RW-P,y);y+=24;
