/* ---------- physics ---------- */
function physics(c,dt,t,live){
 const cx=c.pose.x+c.ox,cy=c.pose.y+c.oy;
 let ax=-c.K*c.ox-c.C*c.vx,ay=-c.K*c.oy-c.C*c.vy,ar=-c.Kr*c.or-c.Cr*c.vr;
 if(live){
  const Ri=140+c.w*.6,dx=cx-mouse.x,dy=cy-mouse.y,d=Math.hypot(dx,dy);
  if(d<Ri){
   const k=(Ri-d)/Ri,sp=Math.min(2200,Math.hypot(mvx,mvy));
   const an=Math.atan2(dy,dx)+c.jit+Math.sin(t*.004+c.ph)*.55;
   const f=(RM?0:2600+sp*2)*k*k;
   ax+=Math.cos(an)*f+(RM?0:mvx*k*.7);ay+=Math.sin(an)*f+(RM?0:mvy*k*.7);
   ar+=c.spin*f*.0025;
   c.hot=Math.min(1.25,c.hot+k*dt*7);
  }
 }
 const vs=Math.hypot(c.vx,c.vy);
 if(vs>40){const w=Math.sin(t*.008+c.ph*3)*vs*1.7;ax+=-c.vy/vs*w;ay+=c.vx/vs*w}
 c.vx+=ax*dt;c.vy+=ay*dt;c.vr+=ar*dt;
 c.ox+=c.vx*dt;c.oy+=c.vy*dt;c.or+=c.vr*dt;
 /* walls keep a card on screen while it is pushed, but never pin it once its own place has scrolled away */
 const m=c.w*.35,nx=c.pose.x+c.ox,ny=c.pose.y+c.oy,wl=Math.min(m,c.pose.x),wr=Math.max(vw-m,c.pose.x),wt=Math.min(70,c.pose.y),wb=Math.max(vh-m,c.pose.y);
 if(nx<wl){c.ox=wl-c.pose.x;c.vx=Math.abs(c.vx)*.72;c.vr+=c.vy*.004}else if(nx>wr){c.ox=wr-c.pose.x;c.vx=-Math.abs(c.vx)*.72;c.vr-=c.vy*.004}
 if(ny<wt){c.oy=wt-c.pose.y;c.vy=Math.abs(c.vy)*.72;c.vr-=c.vx*.004}else if(ny>wb){c.oy=wb-c.pose.y;c.vy=-Math.abs(c.vy)*.72;c.vr+=c.vx*.004}
 c.hot=Math.max(0,c.hot-dt*1.6);
 /* hover lifts the card; it never crumples (the crumple belongs to the receipt) */
 c.vc+=(110*(0-c.c)-17*c.vc)*dt;c.c=clamp(c.c+c.vc*dt,0,1.04);
}
