  if(hubScS>.045&&!hub.classList.contains('away'))hub.classList.add('away');
  else if(hubScS<.02&&hub.classList.contains('away'))hub.classList.remove('away');
  landL=clamp(1-hr.top/Math.max(1,land.clientHeight),0,1);
  landS=Math.abs(landL-landS)<.0005?landL:lerp(landS,landL,1-Math.exp(-dt*11));
  if(landS>.95&&!hub.classList.contains('in'))hub.classList.add('in');
