 html.classList.toggle('past-land',landS>.9||mode!=='idle'||hr.top<-vh*.5);
 ribFrame(dt,hr);
 if(mode==='idle')cards.forEach(c=>{const p=fanPose(c);c.pose={x:p.x+hr.left,y:p.y+hr.top,r:p.r,s:p.s,a:p.a,f:p.f}});
