 if(ctag.classList.contains('on')){tagp.x=lerp(tagp.x,mouse.x+16,.25);tagp.y=lerp(tagp.y,mouse.y+16,.25);ctag.style.translate=`${tagp.x}px ${tagp.y}px`}else{tagp.x=mouse.x+16;tagp.y=mouse.y+16}
